// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.prank(address(this));
        c.AdjustBetAmounts(amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("OpenToThePublic()"));
        assertTrue(!ok);
    }
}
